package ro.leo.systemtests;
import android.accessibilityservice.AccessibilityServiceInfo;import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;
/** Leo remains a normal running app. Only this package's silent fixture is opened/dismissed. */
public final class LeoNotificationsIntegrationTests extends NativeSystemUiTests {
 final String title="LEO SIX LOCAL NOTICE";NotificationManager notices;
 boolean ownActive(){for(android.service.notification.StatusBarNotification n:notices.getActiveNotifications())if(n.getId()==827&&"six-ui".equals(n.getTag()))return true;return false;}
 AccessibilityNodeInfo ownRow(){AccessibilityNodeInfo root=root("ro.leo.visual");return findText(root,title,new int[]{0});}
 void selectOwn()throws Exception{for(int n=0;n<24;n++){AccessibilityNodeInfo row=ownRow();for(AccessibilityNodeInfo node=row;node!=null;node=node.getParent())if(node.isSelected())return;key(KeyEvent.KEYCODE_DPAD_DOWN);}throw new AssertionError("Own fixture did not obtain selection");}
 void openLeo()throws Exception{shell("input keyevent 224");shell("am start -n ro.leo.visual/.NotificationsActivity");check(root("ro.leo.visual")!=null,"Leo notification page opens");AccessibilityNodeInfo page=root("ro.leo.visual");if(findText(page,"nu sunt disponibile",new int[]{0})!=null||findText(page,"not available",new int[]{0})!=null){key(KeyEvent.KEYCODE_MENU);SystemClock.sleep(3000);}for(int n=0;n<2;n++){selectOwn();AccessibilityNodeInfo r=root("ro.leo.visual");if(findText(r,"#",new int[]{0})!=null)return;key(KeyEvent.KEYCODE_DPAD_CENTER);}throw new AssertionError("Unable to reach direct notification list");}
 public void onStart(){Bundle result=new Bundle();AccessibilityServiceInfo info=automation().getServiceInfo();int flags=info.flags;notices=(NotificationManager)getTargetContext().getSystemService(Context.NOTIFICATION_SERVICE);try{
 info.flags|=AccessibilityServiceInfo.FLAG_INCLUDE_NOT_IMPORTANT_VIEWS|AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;automation().setServiceInfo(info);shell("input keyevent 224");NotificationChannel channel=new NotificationChannel("six-ui-local","Leo silent local UI check",NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);channel.enableVibration(false);notices.createNotificationChannel(channel);
 Intent open=new Intent(getTargetContext(),KeypadFixtureActivity.class).putExtra("notification_probe",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent target=PendingIntent.getActivity(getTargetContext(),827,open,PendingIntent.FLAG_CANCEL_CURRENT);String body="Synthetic fixture only. "+new String(new char[320]).replace('\0','x')+" LOCAL FULL DETAIL";
 notices.notify("six-ui",827,new Notification.Builder(getTargetContext(),"six-ui-local").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText("Synthetic content only").setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(target).build());for(int n=0;n<30&&!ownActive();n++)SystemClock.sleep(100);check(ownActive(),"own fixture posted");openLeo();selectOwn();key(KeyEvent.KEYCODE_DPAD_CENTER);check(waitText("ro.leo.systemtests","LOCAL NOTIFICATION OPENED"),"OK opens only fixture destination directly");
 openLeo();selectOwn();key(KeyEvent.KEYCODE_STAR);check(waitText("ro.leo.visual","LOCAL FULL DETAIL"),"star opens complete detail beyond preview limit");key(KeyEvent.KEYCODE_BACK);selectOwn();int previous=root("ro.leo.visual").getWindowId();key(KeyEvent.KEYCODE_POUND);check(root("ro.leo.visual").getWindowId()!=previous,"hash opens additional options");capture("six-notification-options.png");key(KeyEvent.KEYCODE_BACK);selectOwn();previous=root("ro.leo.visual").getWindowId();key(KeyEvent.KEYCODE_5);check(root("ro.leo.visual").getWindowId()!=previous,"5 opens confirmation dialog");check(ownActive(),"fixture not dismissed before confirmation");key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_CENTER);for(int n=0;n<30&&ownActive();n++)SystemClock.sleep(100);check(!ownActive(),"confirmation dismisses only own fixture");result.putString("result","PASS "+checks+" live Leo notification checks");
 }catch(Throwable t){result.putString("error",android.util.Log.getStackTraceString(t));}finally{notices.cancel("six-ui",827);notices.deleteNotificationChannel("six-ui-local");info.flags=flags;automation().setServiceInfo(info);}finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
